package com.smartmanager.nativeapp;
import java.io.IOException;import java.util.*;
/** RouterOS read repository for network modules; no destructive operations are exposed. */
public final class NetworkService { private final RouterService r; public NetworkService(RouterService r){this.r=r;} public List<Map<String,String>> read(String s,String t)throws IOException{String c=command(s,t);return r.execute(c,"=.proplist=.id,name,interface,status,disabled,rx-byte,tx-byte,rate-limit,address,network,server,mac-address,bytes-in,bytes-out,chain,action,src-address,dst-address,comment");} private String command(String s,String t){if("interfaces".equals(s))return "/interface/print";if("ip".equals(s))return "/ip/address/print";if("dhcp".equals(s))return "servers".equals(t)?"/ip/dhcp-server/print":"networks".equals(t)?"/ip/dhcp-server/network/print":"/ip/dhcp-server/lease/print";if("dns".equals(s))return "static".equals(t)?"/ip/dns/static/print":"/ip/dns/print";if("queues".equals(s))return "/queue/simple/print";if("firewall".equals(s))return "nat".equals(t)?"/ip/firewall/nat/print":"address".equals(t)?"/ip/firewall/address-list/print":"mangle".equals(t)?"/ip/firewall/mangle/print":"/ip/firewall/filter/print";return "/system/resource/print";} }
